1	package main
2	
3	import (
4		"cmp"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11	
12		"github.com/integrio-intropy/intropy-cli/internal/blueprint"
13		"github.com/integrio-intropy/intropy-cli/internal/skill"
14		"github.com/integrio-intropy/intropy-cli/internal/skill/oci"
15		"golang.org/x/term"
16	)
17	
18	// The official Intropy skills collection offered by `int create`.
19	const (
20		defaultSkillsCollectionAlias = "intropy"
21		defaultSkillsCollectionRef   = "harbor.intropy.io/skills/index:latest"
22	)
23	
24	// skillsCollectionRef returns the collection to offer, overridable via
25	// INTROPY_SKILLS_COLLECTION (useful for testing against a local registry).
26	func skillsCollectionRef() string {
27		return cmp.Or(os.Getenv("INTROPY_SKILLS_COLLECTION"), defaultSkillsCollectionRef)
28	}
29	
30	// decideInstallSkills is the pure gating logic for the post-scaffold skills
31	// install: --skip-install-skills forces a no and --install-skills forces a
32	// yes, both without prompting; otherwise --no-input and non-terminal stdin
33	// skip, and an interactive session gets a [Y/n] prompt (default yes).
34	func decideInstallSkills(force, skip, noInput bool, in io.Reader, errW io.Writer) (bool, error) {
35		if skip {
36			return false, nil
37		}
38		if force {
39			return true, nil
40		}
41		if noInput {
42			return false, nil
43		}
44		f, ok := in.(*os.File)
45		if !ok || !term.IsTerminal(int(f.Fd())) {
46			return false, nil
47		}
48		return confirmInstallSkills(in, errW)
49	}
50	
51	// maybeInstallSkills applies decideInstallSkills and, on yes, does the
52	// equivalent of `skills collection add` plus `skills add` for every skill in
53	// the collection. On no, it prints how to install later — unless the skip
54	// was the explicit --skip-install-skills, where a hint would just be noise.
55	func maybeInstallSkills(ctx context.Context, in io.Reader, errW io.Writer, force, skip, noInput bool, outputDir string) error {
56		install, err := decideInstallSkills(force, skip, noInput, in, errW)
57		if err != nil {
58			return err
59		}
60		ref := skillsCollectionRef()
61		if !install {
62			if !skip {
63				fmt.Fprintf(errW, "skills not installed — run 'intropy skills collection add --name %s --ref %s' in the integration later\n",
64					defaultSkillsCollectionAlias, ref)
65			}
66			return nil
67		}
68	
69		project, err := skillProjectAt(outputDir)
70		if err != nil {
71			return err
72		}
73		client, err := oci.NewClient()
74		if err != nil {
75			return err
76		}
77		installer := skill.NewInstaller(client, skill.NewTarGzExtractor(), project)
78		adder := skill.NewAdder(client, installer, project)
79	
80		entries, err := skill.NewCollectionInstaller(client, adder, project).
81			InstallAll(ctx, defaultSkillsCollectionAlias, ref)
82		if err != nil {
83			return err
84		}
85		for _, e := range entries {
86			fmt.Fprintf(errW, "  installed %s @ %s -> %s\n", e.Name, e.Source.Tag, e.Path)
87		}
88		fmt.Fprintf(errW, "installed %d skill(s) from %s\n", len(entries), ref)
89		return nil
90	}
91	
92	// confirmInstallSkills renders a [Y/n] prompt (default yes) and reads the
93	// answer. EOF counts as a decline, not an error.
94	func confirmInstallSkills(in io.Reader, out io.Writer) (bool, error) {
95		v, err := blueprint.NewStdinPrompter(in, out).Prompt(blueprint.FieldSpec{
96			Name:    "install-skills",
97			Title:   "Install agent skills into .agents/skills?",
98			Type:    "boolean",
99			Default: true,
100		})
101		if errors.Is(err, io.EOF) {
102			return false, nil
103		}
104		if err != nil {
105			return false, err
106		}
107		b, ok := v.(bool)
108		return ok && b, nil
109	}
110	
111	// skillProjectAt returns the skills project rooted exactly at dir, creating an
112	// empty skills.json there if the blueprint didn't ship one. Unlike
113	// resolveOrBootstrapProject it never walks up: the scaffolded integration is
114	// its own skills project even when created inside a larger repo.
115	func skillProjectAt(dir string) (*skill.Project, error) {
116		abs, err := filepath.Abs(dir)
117		if err != nil {
118			return nil, err
119		}
120		p := &skill.Project{Root: abs}
121		if _, err := os.Stat(p.ManifestPath()); err == nil {
122			return p, nil
123		} else if !os.IsNotExist(err) {
124			return nil, err
125		}
126		if err := p.SaveManifest(&skill.Manifest{Skills: []skill.ManifestEntry{}}); err != nil {
127			return nil, fmt.Errorf("bootstrap skills.json: %w", err)
128		}
129		return p, nil
130	}
